import asyncio
import inspect
from typing import TYPE_CHECKING, Any, Callable, Type, get_origin, get_type_hints

from jsonschema import ValidationError, validate
from pydantic import BaseModel, TypeAdapter, create_model

from dspy.adapters.types.base_type import Type
from dspy.dsp.utils.settings import settings
from dspy.utils.callback import with_callbacks

if TYPE_CHECKING:
    import mcp
    from langchain.tools import BaseTool

_TYPE_MAPPING = {
    "string": str,
    "integer": int,
    "number": float,
    "boolean": bool,
    "array": list,
    "object": dict
}


class ToolCalls(Type):
    class ToolCall(BaseModel):
        name: str
        args: dict[str, Any]

    tool_calls: list[ToolCall]

    @classmethod
    def validate_input(cls, data: dict) -> Any:
        if isinstance(data, dict) and 'tool_calls' in data:
            return data
        elif isinstance(data, list):
            return {'tool_calls': data}
        elif isinstance(data, dict) and 'name' in data and 'args' in data:
            return {'tool_calls': [data]}
        else:
            return data
